import { interp2 } from "@ship/math"
import { atmosphere } from "@ship/earth"
import { normalShock, S } from "./air"
import { nuElectronNeutral } from "./plasma"

/**
 * Precomputed real-gas normal-shock / stagnation table on (altitude, velocity).
 * Generated by scripts/gen-tables.ts into shock-table.json (the solver costs ~2 ms per point).
 */
export interface ShockTable {
  readonly hs: number[] // m
  readonly us: number[] // m/s
  readonly fields: Record<ShockField, number[]>
}
export type ShockField = "eps" | "T2" | "T0" | "p0" | "rho0" | "ne0" | "n0" | "nuEn0" | "cpMax" | "h0" | "gammaE"
export const SHOCK_FIELDS: readonly ShockField[] = ["eps", "T2", "T0", "p0", "rho0", "ne0", "n0", "nuEn0", "cpMax", "h0", "gammaE"]

export const buildShockTable = (hs: number[], us: number[]): ShockTable => {
  const fields = Object.fromEntries(SHOCK_FIELDS.map((f) => [f, [] as number[]])) as Record<ShockField, number[]>
  for (const h of hs) {
    const a = atmosphere(h)
    for (const U of us) {
      const r = normalShock(a.T, a.rho, U)
      const s0 = r.s0
      fields.eps.push(r.eps)
      fields.T2.push(r.s2.T)
      fields.T0.push(s0.T)
      fields.p0.push(s0.p)
      fields.rho0.push(s0.rho)
      fields.ne0.push(Math.log(Math.max(s0.n[S.e], 1)))
      fields.n0.push(Math.log(s0.ntot))
      fields.nuEn0.push(Math.log(Math.max(nuElectronNeutral(s0), 1)))
      fields.cpMax.push(r.cpMax)
      fields.h0.push(s0.h)
      fields.gammaE.push(s0.h / Math.max(s0.h - s0.p / s0.rho, 1e-6))
    }
  }
  return { hs, us, fields }
}

export interface StagState {
  readonly eps: number
  readonly T2: number
  readonly T0: number
  readonly p0: number
  readonly rho0: number
  readonly ne0: number
  readonly n0: number
  readonly nuEn0: number
  readonly cpMax: number
  readonly h0: number
  readonly gammaE: number
}

export const lookupStag = (t: ShockTable, h: number, U: number): StagState => {
  const f = (k: ShockField): number => interp2(t.hs, t.us, t.fields[k], h, U)
  return {
    eps: f("eps"), T2: f("T2"), T0: f("T0"), p0: f("p0"), rho0: f("rho0"),
    ne0: Math.exp(f("ne0")), n0: Math.exp(f("n0")), nuEn0: Math.exp(f("nuEn0")),
    cpMax: f("cpMax"), h0: f("h0"), gammaE: f("gammaE"),
  }
}

export const DEFAULT_GRID = {
  hs: Array.from({ length: 53 }, (_, i) => i * 2500), // 0 … 130 km
  us: Array.from({ length: 42 }, (_, i) => 100 + i * 200), // 100 … 8300 m/s
}
